/**
 * Ash AI: identity and the one-time welcome notification.
 * The notification text is fixed (never generated by Gemini); edit it here.
 */
const assistant = {
  name: "Ash AI",
  /** Only for the AI assistant; Ashish's own photo stays in configs/user.ts. */
  avatar: "img/ui/ash-ai.png",
  welcomeNotification: {
    title: "Ash AI",
    message:
      "Hey, welcome to my portfolio! 👋 Want to know more about my projects, skills, or experience? Chat with my AI assistant.",
    /** Shown this long after the desktop appears (after login). */
    delayMs: 5000,
    /** Dismissed automatically after this long without interaction. */
    autoDismissMs: 10000,
    /** sessionStorage key: shown at most once per browser session. */
    sessionKey: "ashish-ai-welcome-shown"
  }
};

/** Window event that switches an open Messages window to the Ash AI conversation. */
export const SHOW_AI_EVENT = "messages:show-ai";

